import * as React from 'react';

import Map, { TILE_LIGHT_NO_LABELS, TILE_SATELLITE } from 'components/ui/Map';
import { DIFFICULTY_EXPERT, DIFFICULTY_NORMAL } from 'config/baseConfig';

const GameMap = (props) => {
    const { game, geoFileName, choices, geoFolder, initialMapHeight, useFullScreen, useClickMarker, markers, onMarkerSet, markerResult } = props;

	const tileProviderKey = game.difficultyLevel === DIFFICULTY_EXPERT 
		? TILE_SATELLITE
		: TILE_LIGHT_NO_LABELS;
		console.log(game);
	const useTonerLines = game.difficultyLevel === DIFFICULTY_NORMAL && game.gameMode === 'map_country';

    return (
		<Map
			tileProviderKey={tileProviderKey}
			geoFileName={geoFileName}
			// choices={choices} // goes with stash
			geoFolder={geoFolder}
			useClickMarker={useClickMarker}
			useFullScreen={useFullScreen}
			initialMapHeight={initialMapHeight}
			markers={markers}
			onMarkerSet={onMarkerSet}
			markerResult={markerResult}
			useTonerLines={useTonerLines}
			maxZoom={14}
		/>
    );
};

export default GameMap;
